import assert from'node:assert/strict';import{mkdtemp,rm,readFile,writeFile}from'node:fs/promises';import{tmpdir}from'node:os';import path from'node:path';import{load}from'cheerio';
import{chromium}from'playwright';import{serveStatic}from'../../engine/static.mjs';
import{localize}from'../../engine/assets.mjs';import{mapWordpress}from'../../engine/wordpress.mjs';
import{recordProduct}from'../../engine/commerce.mjs';import{extract}from'../../engine/extract.mjs';import{generate}from'../../engine/generate.mjs';import{run}from'../../engine/pipeline.mjs';import{parseContent,YAML}from'../../scripts/source-project.mjs';
let browser,server;const origin='http://127.0.0.1:9427',dir=await mkdtemp(path.join(tmpdir(),'installed-commerce-'));
try{
 const response=await fetch(origin+'/wp-json/wc/store/v1/products');assert.equal(response.status,200);const rows=await response.json();assert.equal(rows.length,2);
 const model={source:origin+'/',identity:{title:'Workshop Store'},design:{},navigation:[],metrics:{},warnings:[],pages:[],media:[],wordpress:{records:{},types:[],taxonomies:[],terms:{}}};
 for(const row of rows){assert.equal(recordProduct(model,row),true);const html=await(await fetch(row.permalink)).text();model.pages.push({...extract(html,row.permalink),styles:[],styleSources:[]});}
 mapWordpress(model);await localize(model,{async get(url){assert.equal(new URL(url).origin,origin,'fixture asset stays local');const response=await fetch(url,{redirect:'manual'});return {status:response.status,url,headers:Object.fromEntries(response.headers),body:Buffer.from(await response.arrayBuffer())};}},path.join(dir,'assets/media'));await generate(model,dir);const routes=JSON.parse(await readFile(path.join(dir,'routes.json'),'utf8'));assert.ok(routes.every(r=>r.collection==='wp-product'));
 const record=routes.find(r=>r.route==='/product/workshop-shirt/'),file=path.join(dir,'content',record.collection,record.slug+'.md'),parsed=parseContent(await readFile(file,'utf8'),file);
 assert.equal(parsed.meta.product.type,'variable');assert.equal(parsed.meta.product.variations.length,2);const small=parsed.meta.product.variations.find(v=>v.attributes[0].value==='Small'),large=parsed.meta.product.variations.find(v=>v.attributes[0].value==='Large');assert.equal(small.snapshot.display_price,29);assert.equal(large.snapshot.display_price,34);assert.equal(small.snapshot.is_in_stock,true);assert.equal(large.snapshot.is_in_stock,false);assert.equal(small.snapshot.price_unit,'major-currency-unit');assert.ok(small.snapshot.image.src.startsWith('/assets/media/'));assert.ok(large.snapshot.image.full.startsWith('/assets/media/'));assert.equal(small.snapshot.image.full_width,1200);assert.equal(parsed.meta.product.gallery[0].full_height,1200);assert.ok(small.snapshot.image.sources.length>1);assert.ok(small.snapshot.image.sources.every(s=>s.url.startsWith('/assets/media/')));assert.ok(parsed.body.includes('Made for everyday work.'));
 parsed.meta.product.gallery[0].alt='Edited front image';parsed.meta.product.gallery[0].caption='Edited gallery caption';parsed.meta.product.sku='EDITED-SHIRT';small.snapshot.display_price=31;await writeFile(file,'---\n'+YAML.stringify(parsed.meta)+'---\n'+parsed.body.replace('Made for everyday work.','Edited for studio work.'));await run(process.execPath,['scripts/build.mjs'],{cwd:dir,timeout:120000});
 const $=load(await readFile(path.join(dir,'output/product/workshop-shirt/index.html'),'utf8'));assert.equal($('.sku').first().text(),'EDITED-SHIRT');const authoredImage=$('.woocommerce-product-gallery__image img').first();assert.equal(authoredImage.attr('src'),parsed.meta.product.gallery[0].src);assert.equal(authoredImage.attr('alt'),'Edited front image');assert.equal(authoredImage.attr('data-caption'),'Edited gallery caption');assert.equal(authoredImage.attr('width'),'1200');assert.ok($.text().includes('Edited for studio work.'));assert.equal($('.single_add_to_cart_button').attr('disabled'),'disabled');assert.equal($('form.cart').attr('action'),undefined);
 server=await serveStatic(path.join(dir,'output'));browser=await chromium.launch({channel:'chrome'});
 for(const width of[1440,390]){const page=await browser.newPage({viewport:{width,height:900}});let posts=0;await page.route('**/*',r=>{if(!['GET','HEAD'].includes(r.request().method())){posts++;return r.abort();}return new URL(r.request().url()).origin===new URL(server.url).origin?r.continue():r.abort();});await page.goto(server.url+'/product/workshop-shirt/',{waitUntil:'networkidle'});
  await page.getByRole('tab',{name:'Additional information',exact:true}).click();assert.equal(await page.locator('#tab-additional_information').isVisible(),true);assert.equal(await page.locator('#tab-description').isVisible(),false);await page.getByRole('tab',{name:'Description',exact:true}).click();assert.equal(await page.locator('#tab-description').isVisible(),true);
  const gallery=page.locator('[data-cloner-gallery-ready]');assert.equal(await gallery.count(),1);const thumbs=gallery.locator('.flex-control-thumbs img');assert.equal(await thumbs.count(),2);await thumbs.nth(1).click();assert.equal(await thumbs.nth(1).getAttribute('aria-pressed'),'true');await gallery.locator('.flex-active-slide a').click();await page.waitForFunction(()=>document.querySelector('.pswp')?.classList.contains('pswp--open'));await page.keyboard.press('Escape');await page.waitForFunction(()=>!document.querySelector('.pswp')?.classList.contains('pswp--open'));await thumbs.nth(1).press('Home');assert.equal(await thumbs.nth(0).getAttribute('aria-pressed'),'true');
  const options=page.locator('select[name="attribute_size"]');assert.equal(await options.isEnabled(),true);await options.selectOption('Small');assert.match(await page.locator('.single_variation').innerText(),/31[.,]00/);assert.equal(await page.locator('.sku').first().innerText(),'SHIRT-SMALL');await options.selectOption('Large');assert.equal(await thumbs.nth(1).getAttribute('aria-pressed'),'true');assert.ok((await gallery.locator('.flex-active-slide img').getAttribute('src')).includes('/assets/media/'));assert.ok((await gallery.locator('.flex-active-slide img').getAttribute('srcset')).includes('/assets/media/'));assert.match(await page.locator('.single_variation').innerText(),/34[.,]00/);assert.match(await page.locator('.single_variation').innerText(),/Out of stock/i);assert.equal(await page.locator('.single_add_to_cart_button').isDisabled(),true);await page.locator('.reset_variations').click();assert.equal(await options.inputValue(),'');assert.equal(await thumbs.nth(0).getAttribute('aria-pressed'),'true');assert.equal(await page.locator('.sku').first().innerText(),'EDITED-SHIRT');await page.locator('form.cart').evaluate(e=>e.requestSubmit());await page.waitForTimeout(50);assert.equal(posts,0);await page.close();
 }
 console.log(JSON.stringify({plugin:'woocommerce',version:'11.2.1',products:2,nativeProductCollection:true,variationPriceStockSnapshots:true,localizedVariationImages:true,galleryThumbnailAndVariationSelection:true,fullscreenOpenAndEscape:true,editedSkuAndMarkdown:true,staticGalleryFrontmatterEdits:true,transactionsDisconnected:true,localOptionsDesktopMobile:true,productTabs:true,editedVariationPrice:true,aiCalls:0,scope:'Installed public catalog and native authoring; gallery fullscreen visual parity and hover zoom, broader variation configurations, checkout services and full plugin acceptance remain pending'}));
}finally{await browser?.close();await server?.close();await rm(dir,{recursive:true,force:true});}
